commands.command:
set -eu
base=/srv/legacy2/web-authentication-boundary
pw=$(sed -n 's/^Demonstration password:[REDACTED]]]]]*//p' "$base/access.txt")
[ -n "$pw" ]
[ "$(printf '%s\n' "$pw" | wc -l)" -eq 1 ]
umask 027
printf '%s\n' "$pw" | htpasswd -i -c -B /etc/nginx/.staff_htpasswd reader >/dev/null
chown root:nginx /etc/nginx/.staff_htpasswd
chmod 640 /etc/nginx/.staff_htpasswd
mv /etc/nginx/http.d/default.conf /etc/nginx/http.d/default.conf.disabled
cat > /etc/nginx/http.d/web-authentication-boundary.conf <<'ANTRIEB_EOF'
server {
    listen 8080 default_server;
    listen [::]:8080 default_server;
    server_name _;

    autoindex off;

    location = /public { return 308 /public/; }
    location ^~ /public/ {
        alias /srv/legacy2/web-authentication-boundary/public/;
        index index.html;
        autoindex off;
    }

    location = /staff { return 308 /staff/; }
    location ^~ /staff/ {
        alias /srv/legacy2/web-authentication-boundary/staff/;
        index index.html;
        autoindex off;
        auth_basic "Staff access";
        auth_basic_user_file /etc/nginx/.staff_htpasswd;
    }

    location = /access.txt { return 404; }
    location / { return 404; }
}
ANTRIEB_EOF
chmod 644 /etc/nginx/http.d/web-authentication-boundary.conf
nginx -t
rc-update add nginx default
rc-service nginx start
rc-service nginx status

